import sys

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        a = list(map(int, sys.stdin.readline().split()))
        max_prod = -1
        for i in range(n):
            temp = a.copy()
            temp[i] += 1
            prod = 1
            for num in temp:
                prod *= num
            if prod > max_prod:
                max_prod = prod
        print(max_prod)

if __name__ == "__main__":
    main()
