import sys

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, k = map(int, sys.stdin.readline().split())
        s = sys.stdin.readline().strip()
        b_positions = []
        for idx, char in enumerate(s):
            if char == 'B':
                b_positions.append(idx)
        if not b_positions:
            print(0)
            continue
        res = 0
        prev_end = -1
        i = 0
        while i < len(b_positions):
            current = b_positions[i]
            if current > prev_end:
                res += 1
                end = current + k - 1
                prev_end = end
                # Move i forward until we pass the current end
                while i < len(b_positions) and b_positions[i] <= end:
                    i += 1
            else:
                # Already covered, move to next
                i += 1
        print(res)

if __name__ == "__main__":
    main()
```

